//! Genuine original source cases, no expected rows or source certificates.
pub const KINDS:&[&str]=&["expiry"];
pub fn name(kind:&str)->&'static str{assert_eq!(kind,"expiry");"sys/expiry"}
pub fn configuration(_: &str,case:usize)->String{let base="[lint.sys]\nexempt_prefixes=[\"code/modules/unit_tests/\"]\n";match case{0|1=>base.into(),2=>format!("{base}[lint.\"sys/expiry\"]\nexempt_prefixes=[\"code/datums/om/decl.dm\",\"maps/z.dm\"]\n"),3=>format!("{base}[lint.\"sys/expiry\".ceilings]\nworld_time_write=100\n"),4=>format!("{base}[lint.\"sys/expiry\"]\nexempt_prefixes=[\"code/a.dm\"]\n"),_=>panic!("fixture case")}}
const FILES:&[(&str,&str)]=&[
("code/a.dm","/obj/control/proc/run()\n\tif(world.time > recorded_at) return\n\tstarted = world.time\n\tCOOLDOWN_RUNNING(src, clock_a)\n\tCOOLDOWN_LAPSED(src, clock_skip)\n\tCOOLDOWN_EXTEND(src, clock_missing, 5)\n\tmember.last = TIME_NOW()\n\tif(world.time > recorded_at) return // ALLOW(cooldown/DATA): this fixture records an original direct cooldown annotation\n\tif(world.time > recorded_at || world.time - other > 5) return // ALLOW(cooldown/DATA, sys_world_time_expiry/KEEP): elapsed fallback preserves both distinct annotation traces\n\tmember.second = world.time // ALLOW(sys_world_time_write): this fixture preserves original outer stored-write annotation\n\tCOOLDOWN_RUNNING(src, unknown) // ALLOW(sys_expiry_undeclared): this fixture preserves original undeclared-use annotation\n\tvar/local = world.time\n\tif(world.time > 5) return\n\tif(world.time > normal_clock) return\n"),
("code/z.dm","STATIC_COOLDOWN_DECLARE(clock_a)\n/obj/control/proc/time_now(var/list/arg, plain = 1)\n\tvar/local\n\tlocal = TIME_NOW()\n\targ = TIME_NOW()\n\tplain = TIME_NOW()\n\tstored = TIME_NOW()\n\tGLOB.last = TIME_NOW()\n\tGLOB.part.member = TIME_NOW()\n\tsrc.other = TIME_NOW()\n\tvar/static/cache = TIME_NOW()\n\tif(world.time - started > 5) return\n\tlast_timestamp = world.time + 1\n\tCOOLDOWN_TIMELEFT_OWN(src, unseen)\n// COOLDOWN_DECLARE(comment_declared)\n\tCOOLDOWN_RUNNING(src, comment_declared)\n"),
("code/datums/om/decl.dm","COOLDOWN_DECLARE(clock_skip)\n\tmember.value = world.time\n\tmember.value = TIME_NOW()\n"),
("code/controllers/processor.dm","/datum/controller/proc/process()\n\tif(world.time > normal_clock) return\n"),
("code/modules/reagents/data.dm","/datum/reagent/proc/read()\n\tif(world.time > data) return\n"),
("maps/z.dm","/obj/mapped/proc/run()\n\tif(world.time > normal_clock) return\n\tlast = world.time\n\tmember.last = TIME_NOW()\n\tCOOLDOWN_RUNNING(src, map_missing)\n"),
("code/.hidden/ignore.dm","\tmember.hidden = world.time\n"),("code/modules/unit_tests/ignore.dm","\tmember.test = world.time\n")];
pub fn files(_: &str,case:usize)->Vec<(&'static str,String)>{let mut rows:Vec<(&'static str,String)>=FILES.iter().map(|(p,s)|(*p,(*s).into())).collect();if case==1{rows.iter_mut().find(|(p,_)|*p=="code/z.dm").unwrap().1.push_str("COOLDOWN_DECLARE(clock_missing)\n");}rows}
